#include <stdint.h>

#if !defined(__SOFT_FP__) && defined(__ARM_FP)
  #warning "FPU is not initialized, but the project is compiling for an FPU. Please initialize the FPU before use."
#endif

int main(void)
{
	uint32_t volatile *const pClkCtrlreg = (uint32_t*)0x40023830;
	uint32_t volatile *const pPortDModeReg = (uint32_t*)0x40020C00;
	uint32_t volatile *const pPortDOutReg = (uint32_t*)0x40020C14;

	uint32_t volatile *const pPortAModeReg = (uint32_t*)0x40020000;
	uint32_t const volatile *const pPortAInpReg = (uint32_t*)0x40020010;

	//Enable RSS Clock for GPIOD in AHB1ENR (SET the 3rd bit position)
	*pClkCtrlreg |= (1 << 3);
	//Enable RCC Clock for GPIOA in AHB1ENR (SET the 1rd bit position)
	*pClkCtrlreg |= 1;
	//LED
	//configure the mode of the LED IO pin as output
	//clear the 24th and 25th bit positions (CLEAR)
	*pPortDModeReg &= ~(3 << 24);
	//make 24th bit position as 1 (SET)
	*pPortDModeReg |= (1 << 24);

	//PORT
	//configure the mode of the input port as input
	//clear the 0 and 1 bit positions (clear)
	*pPortAModeReg &= ~3;

	uint32_t inputData = 0;
    /* Loop forever */
	while(1){
		inputData = *pPortAInpReg & 0x01;

		if(inputData == 1)
		{
			//SET 12th bit of the output data register to make IO pin-12 HIGH
			*pPortDOutReg |= (1 << 12);
		}
		else
		{
			//SET 12th bit of the output data register to make IO pin-12 LOW
			*pPortDOutReg &= ~(1 << 12);
		}
	}
}
